solutions.naive:
class Solution:
    def isHappy(self, n: int) -> bool:
        def nxt(x: int) -> int:
            total = 0
            while x:
                digit = x % 10
                total += digit * digit
                x //= 10
            return total

        for _ in range(1000):
            if n == 1:
                return True
            n = nxt(n)
        return False

