class Solution:
    def isHappy(self, n: int) -> bool:
        def nxt(x: int) -> int:
            return sum(int(ch) ** 2 for ch in str(x))

        seen = set()
        while n != 1 and n not in seen:
            seen.add(n)
            n = nxt(n)
        return n == 1

