class Solution:
    def isHappy(self, n: int) -> bool:
        def nxt(x: int) -> int:
            total = 0
            while x:
                digit = x % 10
                total += digit * digit
                x //= 10
            return total

        slow, fast = n, nxt(n)
        while fast != 1 and slow != fast:
            slow = nxt(slow)
            fast = nxt(nxt(fast))
        return fast == 1

